package org.dromara.property.resident.service.impl;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page; import org.dromara.common.core.exception.ServiceException; import org.dromara.common.mybatis.core.page.PageQuery; import org.dromara.property.resident.domain.bo.ResidentQueryBo; import org.dromara.property.resident.domain.vo.ResidentRelationVo; import org.dromara.property.resident.mapper.ResidentMapper; import org.dromara.property.scope.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class ResidentServiceImplTest {
 @Mock ResidentMapper mapper; @Mock PropertyProjectScopeService scopes; @Mock PropertyFunctionalPermissionService permissions; ResidentServiceImpl service;
 @BeforeEach void init(){service=new ResidentServiceImpl(mapper,scopes,permissions);}
 @Test void projectOutsideCustomerRelationScopeReturnsNoRows(){when(scopes.resolveBusinessScope(PropertyBusinessDomain.CUSTOMER_RELATION,ProjectBusinessAction.READ)).thenReturn(PropertyProjectScope.explicit(Set.of(1L)));var bo=new ResidentQueryBo();bo.setProjectId(2L);assertEquals(0,service.queryPage(bo,new PageQuery()).getTotal());verifyNoInteractions(mapper);}
 @Test void listUsesRelationRowsAndExplicitScope(){when(scopes.resolveBusinessScope(any(),any())).thenReturn(PropertyProjectScope.explicit(Set.of(1L)));var bo=new ResidentQueryBo();bo.setProjectId(1L);var page=new Page<ResidentRelationVo>();page.setRecords(List.of(row("ACTIVE"),row("ACTIVE")));page.setTotal(2);when(mapper.selectPage(any(),eq(bo),eq(Set.of(1L)))).thenReturn(page);assertEquals(2,service.queryPage(bo,new PageQuery()).getRows().size());}
 @Test void detailSeparatesCurrentPendingHistory(){when(scopes.resolveBusinessScope(any(),any())).thenReturn(PropertyProjectScope.explicit(Set.of(1L)));when(mapper.selectCustomerRelations(9L,1L,Set.of(1L))).thenReturn(List.of(row("ACTIVE"),row("PENDING"),row("ENDED")));var d=service.queryDetail(9L,1L);assertAll(()->assertEquals(1,d.getCurrentRelations().size()),()->assertEquals(1,d.getPendingRelations().size()),()->assertEquals(1,d.getHistoryRelations().size()));}
 @Test void detailIdorIsRejectedBeforeQuery(){when(scopes.resolveBusinessScope(any(),any())).thenReturn(PropertyProjectScope.explicit(Set.of(1L)));assertThrows(ServiceException.class,()->service.queryDetail(9L,2L));verifyNoInteractions(mapper);}
 private ResidentRelationVo row(String status){var r=new ResidentRelationVo();r.setCustomerId(9L);r.setCustomerNo("C9");r.setMaskedCustomerName("张*");r.setRelationStatus(status);return r;}
}
